<template><Card><h2>{{rule?'佣金规则':'合作协议'}}</h2><StatusPanel :error="error" :pending="pending" :busy="busy" :loading="loading" @recover="recover" @retry="retryOriginal" @abandon="abandonPending"/><div class="s1-toolbar"><Input v-model="targetStore" placeholder="按店铺编号筛选" style="width:230px"/><Button @click="page=1;reload()">查询</Button><Button v-if="writable" type="primary" :disabled="pending||uploadsPending" @click="edit(null,false)">新建{{rule?'规则':'协议'}}草稿</Button></div><Table :data="records" :columns="columns" :loading="loading" no-data-text="暂无记录"><template slot="name" slot-scope="{row}">{{row.payload.name||'未命名草稿'}}</template><template slot="status" slot-scope="{row}">{{label(row.status)}}</template><template slot="action" slot-scope="{row}"><Button size="small" @click="detail(row)">详情与历史</Button><Button v-if="writable&&row.status==='DRAFT'" size="small" :disabled="pending||uploadsPending" @click="edit(row,false)">编辑</Button><Button v-if="writable&&row.status!=='DRAFT'" size="small" :disabled="pending||uploadsPending" @click="edit(row,true)">创建续约版本</Button></template></Table><Page :total="total" :current="page" :page-size="size" show-total @on-change="page=$event;reload()"/><Drawer v-model="show" :title="rule?'规则草稿':'协议草稿'" width="850" :mask-closable="false" :closable="!uploadsPending"><FieldsForm v-model="header" :fields="headerFields" :disabled="busy||pending||uploadsPending"/><Button v-if="!rule&&header.storeId" :disabled="busy||pending||uploadsPending" @click="useStore">从当前批准资料填入主体和范围</Button><FieldsForm v-model="form" :fields="fields" :disabled="busy||pending||uploadsPending"/><FileField v-if="!rule&&show" :key="(editing?editing.id:previous?previous.id:'new')+':'+header.storeId" v-model="form.fileIds" :receipt-key="(editing?editing.id:previous?previous.id:'new')+':'+header.storeId" purpose="AGREEMENT" title="协议附件" protected-hint="仅授权人员可预览" multiple :disabled="busy||pending||uploadsPending" @preview="preview" @pending="uploading=$event"/><Button type="primary" :loading="busy" :disabled="pending||uploading||uploadsPending" @click="save">保存草稿</Button></Drawer><Drawer v-model="detailShow" title="当前版本和历史" width="85"><template v-if="selected"><div v-if="writable" class="s1-toolbar"><Button v-if="selected.status==='DRAFT'" type="primary" :disabled="busy||pending||uploadsPending" @click="command(rule?'publish':'confirm')">{{rule?'发布当前规则版本':'确认当前协议版本'}}</Button><Button v-if="!rule&&selected.status==='CONFIRMED'" :disabled="busy||pending||uploadsPending" @click="command('cancel')">取消待生效协议</Button><Button v-if="!rule&&selected.status==='EFFECTIVE'" type="error" :disabled="busy||pending||uploadsPending" @click="command('terminate')">立即终止协议</Button><Button v-if="rule&&['EFFECTIVE','CONFIRMED'].includes(selected.status)" type="warning" :disabled="busy||pending||uploadsPending" @click="command('disable')">停用规则</Button></div><RecordDetail :value="selected" @preview="preview"/><RulePreview v-if="rule" :key="selected.id" :rule="selected"/><h3>版本历史</h3><RecordDetail v-for="item in history" :key="item.id" :value="item" @preview="preview"/></template></Drawer></Card></template>
<script>
import RulePreview from './RulePreview';import {pageMixin} from './shared';import {s1Read} from '@/api/stage1';import FileField from './FileField';import FieldsForm from './FieldsForm';import StatusPanel from './StatusPanel';import RecordDetail from './RecordDetail';
const baseCode='PRODUCT_PAID_EXCLUDING_SHIPPING',roundCode='FLOOR_CENT';
export default {props:{rule:Boolean},mixins:[pageMixin],components:{RulePreview,FieldsForm,StatusPanel,RecordDetail,FileField},data:()=>({show:false,detailShow:false,editing:null,previous:null,form:{},header:{},targetStore:'',history:[],storeCategories:[],stores:[],agreements:[],uploading:false,columns:[{title:'名称',slot:'name',minWidth:180},{title:'店铺编号',key:'storeId',minWidth:180},{title:'状态',slot:'status',width:110},{title:'协议/规则版本',key:'revision',width:120},{title:'数据版本',key:'version',width:100},{title:'操作',slot:'action',width:300}]}),computed:{path(){return this.rule?'/commission-rules':'/agreements';},writable(){return this.can(this.rule?'rule.write':'agreement.write');},headerFields(){return [{key:'storeId',label:'店铺编号',required:true,disabled:!!this.editing,max:19,help:'从商户管理复制准确店铺编号；续约版本保持原店铺。'},...(this.rule?[{key:'agreementId',label:'引用协议编号',required:true,disabled:!!this.editing,max:19,help:'引用已确认的协议及其版本，发布前重新检查生效窗口。'}]:[])];},fields(){return [{key:'name',label:'名称',required:true,max:this.rule?60:100},...(!this.rule?[{key:'platformLegalName',label:'平台主体名称',required:true,max:100},{key:'merchantLegalName',label:'商户主体名称',required:true,max:100},{key:'merchantLegalCode',label:'统一社会信用代码',required:true,max:18},{key:'categoryIds',label:'合作类目范围',type:'multi',required:true,options:(this.storeCategories||[]).map(id=>({value:id,label:id}))},{key:'confirmationReference',label:'双方确认凭据',required:true,max:255}]:[]),{key:'startDate',label:'生效开始日期',required:true,placeholder:'YYYY-MM-DD'},{key:'endDate',label:'生效结束日期',required:true,placeholder:'YYYY-MM-DD',help:'Asia/Shanghai；截止包含该日期全天。'},{key:'rateBps',label:'佣金比例（万分比）',type:'integer',min:0,max:10000,required:true,help:'例如 250 表示 2.50%；0 是明确免佣，不等于未填写。'},{key:'commissionClause',label:'佣金条款',type:'textarea',required:true,max:2000},...(this.rule?[{key:'executionIntent',label:'未来执行意图',type:'boolean',help:'仅保留商业意图，本阶段不执行资金。'},{key:'note',label:'备注',type:'textarea',max:500}]:[{key:'refundSummary',label:'退款规则摘要',type:'textarea',required:true,max:2000}])];}},mounted(){this.targetStore=String(this.$route.query.targetStore||'');this.reload();},methods:{reload(){return this.load(this.path,{targetStore:this.targetStore||undefined});},async edit(row,renew){this.editing=renew?null:row;this.previous=renew?row:null;this.header={storeId:row?row.storeId:this.targetStore,...(this.rule?{agreementId:row?row.agreementId:''}:{})};this.form=row?JSON.parse(JSON.stringify(row.payload)):{name:'',baseCode,roundCode,...(this.rule?{triggerBasis:'ORDER_COMPLETED_NO_BLOCKING_AFTERSALE',executionIntent:false}:{categoryIds:[],fileIds:[]})};this.storeCategories=this.form.categoryIds||[];this.show=true;},async useStore(){try{const profile=await s1Read('/stores/'+this.header.storeId);this.storeCategories=profile.categoryIds;this.form={...this.form,merchantLegalName:profile.legalName,merchantLegalCode:profile.legalCode,categoryIds:[...profile.categoryIds]};}catch(e){this.error=e.message;}},async save(){try{const body=this.editing?{expectedVersion:this.editing.version,payload:this.form}:{...this.header,businessType:'MALL',...(this.previous?{predecessorId:this.previous.id}:{}),payload:this.form};await this.run(this.path+(this.editing?'/'+this.editing.id+'/draft':''),body,this.editing?'PUT':'POST');this.show=false;await this.reload();}catch(_){}},async detail(row){try{this.selected=await s1Read(this.path+'/'+row.id);this.history=await s1Read(this.path+'/'+row.id+'/versions');this.detailShow=true;}catch(e){this.error=e.message;}},async command(action){const row=this.selected;const result=await this.reasonAction(this.path+'/'+row.id+'/'+action,{confirm:'确认协议后正文不可原地覆盖',publish:'发布规则并校验协议、条款及时间窗口',cancel:'取消尚未生效的协议',terminate:'立即终止协议',disable:'立即停用规则'}[action],{expectedVersion:row.version});if(result){await this.detail(row);await this.reload();}}}};
</script>
<style scoped>.s1-toolbar{display:flex;gap:12px;margin:18px 0}.ivu-page,section{margin:18px 0}.ivu-btn{margin-right:8px}section>div{padding:8px 0}</style>
